def load_steps(fname):
    data = json.loads((HERE / fname).read_text())
    rows = data.get("steps") or data.get("results") or []
    return {(r.get("step") or r.get("check")): r["pass"] for r in rows}


errors, cache = [], {}
for nid, (label, deps, ev, _) in N.items():
    if label not in LABELS:
        errors.append(f"{nid}: unknown label {label}")
    for d in deps:
        if d not in N:
            errors.append(f"{nid}: unknown dependency {d}")
    if label in ("DERIVED", "NUMERICAL_CHECK") and not ev:
        errors.append(f"{nid}: {label} without evidence")
    for fname, prefixes in ev:
        if fname not in cache:
            try:
                cache[fname] = load_steps(fname)
            except FileNotFoundError:
                errors.append(f"{nid}: missing results file {fname}"); cache[fname] = {}
        for pre in prefixes:
            hits = [ok for name, ok in cache[fname].items() if name.split(".")[0].split(" ")[0] == pre]
            if not hits:
                errors.append(f"{nid}: step {pre} not found in {fname}")
            elif not all(hits):
                errors.append(f"{nid}: step {pre} FAILED in {fname}")


def ancestors(nid, seen=None):
    seen = set() if seen is None else seen
    for d in N[nid][1]:
        if d not in seen:
            seen.add(d); ancestors(d, seen)
    return seen


report = {}
for out in OUTPUTS:
    anc = ancestors(out) | {out}
    by = {lab: sorted(a for a in anc if N[a][0] == lab) for lab in ("AXIOM", "IMPORTED_THEOREM", "OPEN", "NUMERICAL_CHECK")}
    report[out] = by
    print(f"{out:16s} [{N[out][0]}] {N[out][3]}")
    print(f"    axioms   : {', '.join(by['AXIOM']) or '-'}")
    print(f"    imported : {', '.join(by['IMPORTED_THEOREM']) or '-'}")
    if by["NUMERICAL_CHECK"]:
        print(f"    numerical: {', '.join(by['NUMERICAL_CHECK'])}")
    if by["OPEN"]:
        print(f"    OPEN     : {', '.join(by['OPEN'])}")
counts = {lab: sum(1 for v in N.values() if v[0] == lab) for lab in sorted(LABELS)}
print("label counts:", counts)
(HERE / "audit_report.json").write_text(json.dumps({"errors": errors, "counts": counts, "outputs": report,
                                                     "nodes": {k: dict(label=v[0], deps=v[1], evidence=v[2], note=v[3]) for k, v in N.items()}}, indent=2))
if errors:
    print("AUDIT ERRORS:"); [print("  " + e) for e in errors]
    sys.exit(1)
print("AUDIT OK: every DERIVED/NUMERICAL node is backed by passing steps; remaining inputs listed above")
